// Map Alexia backend (FastAPI /api/v1) payloads onto the dashboard's view models in src/types/*.
// The backend keeps its own field names; these adapters are the single place they are translated.
import { DeploymentRecord, DeploymentStatus } from '../types/services';
import { SnapshotRecord } from '../types/audit';
import { ReportType, SecurityReport } from '../types/reports';
import { ScenarioDefinition, ScenarioId } from '../types/scenarios';

const REPORT_DISCLAIMER =
  'DRAFT generated by Alexia. Not legal advice. Review with your legal or compliance contact before submission.';

type Json = Record<string, any>;

const DEPLOY_STATUS: Record<string, DeploymentStatus> = {
  deploying: 'Deploying',
  healthy: 'Successful',
  rolled_back: 'Rolled back',
  failed: 'Failed',
  pending: 'Pending',
  verifying: 'Verifying',
};

export function toDeploymentRecord(dep: Json): DeploymentRecord {
  const service = dep.service_name || 'shoplite-api';
  const review = dep.pre_deploy_review ?? dep.pre_deploy_Review ?? 'pending';
  const health = dep.health_gate ?? 'pending';
  const timestamp = dep.timestamp || new Date().toISOString();
  return {
    id: dep.id,
    service_name: service,
    image_tag: `${service}:${dep.version ?? 'unknown'}`,
    previous_known_good_image: `${service}:${dep.previous_version ?? 'unknown'}`,
    trigger: dep.author === 'Builder Agent' ? 'alexia_remediation' : 'git_push',
    status: DEPLOY_STATUS[dep.status] ?? 'Pending',
    started_at: timestamp,
    completed_at: dep.status === 'deploying' ? undefined : timestamp,
    pre_deploy_gates: [
      { name: 'Builder review · Sentinel secret scan · Integrity migration guard', passed: review === 'passed', details: `${review} — commit ${dep.commit_sha ?? ''}`.trim(), timestamp },
    ],
    health_gates: [
      { name: '3-minute health gate (/health, 5xx rate, restarts)', passed: health === 'passed', details: dep.notes ?? health, timestamp },
    ],
    rollback_info:
      dep.status === 'rolled_back'
        ? { is_rollback: true, target_image: `${service}:${dep.previous_version ?? 'unknown'}`, reason: dep.notes ?? '', executed_at: timestamp }
        : undefined,
    rollback_available: Boolean(dep.rollback_available),
  };
}

const SNAPSHOT_TYPE: Record<string, SnapshotRecord['snapshot_type']> = {
  full_bundle: 'postgres_pg_dump',
  config_env: 'state_diff',
  container_image: 'container_fs',
};

export function toSnapshotRecord(snap: Json): SnapshotRecord {
  return {
    id: snap.id,
    timestamp: snap.created_at || new Date().toISOString(),
    triggering_incident_id: snap.incident_id,
    trigger_action: snap.incident_id === 'manual_operator' ? 'Manual operator snapshot' : `Pre-action snapshot for ${snap.incident_id}`,
    snapshot_type: SNAPSHOT_TYPE[snap.type] ?? 'state_diff',
    target_resource: snap.service_name || 'shoplite-api',
    size_bytes: Math.round((Number(snap.size_mb) || 0) * 1024 * 1024),
    sha256_checksum: snap.sha256 || '',
    integrity_status: snap.verified ? 'valid' : 'unverified',
    restore_eligible: Boolean(snap.restorable),
    related_audit_id: '',
  };
}

const REPORT_TYPE: Record<string, ReportType> = {
  'CERT-In': 'cert_in',
  DPDP_ACT: 'dpdp_detailed',
  GDPR: 'gdpr_draft',
};

/** Split a markdown draft into heading/content sections (## / ### headings). */
function markdownSections(md: string): SecurityReport['sections'] {
  const sections: SecurityReport['sections'] = [];
  let current: { heading: string; lines: string[] } | null = null;
  for (const line of md.split('\n')) {
    const m = line.match(/^#{1,4}\s+(.*)$/);
    if (m) {
      if (current) sections.push({ heading: current.heading, content: current.lines.join('\n').trim() });
      current = { heading: m[1].trim(), lines: [] };
    } else {
      (current ??= { heading: 'Draft', lines: [] }).lines.push(line);
    }
  }
  if (current) sections.push({ heading: current.heading, content: current.lines.join('\n').trim() });
  return sections.filter((s) => s.content || s.heading);
}

export function toSecurityReport(rep: Json): SecurityReport {
  const sections = rep.markdown
    ? markdownSections(String(rep.markdown))
    : [
        { heading: 'Summary', content: rep.summary ?? '' },
        { heading: 'Root cause', content: rep.root_cause ?? '' },
        {
          heading: 'Data exposed',
          content: `${(rep.data_categories_exposed ?? []).join(', ') || 'None identified'}\nEstimated records affected: ${rep.affected_records_estimate ?? 0}`,
        },
        { heading: 'Containment actions taken', content: (rep.containment_actions_taken ?? []).map((a: string) => `• ${a}`).join('\n') },
        { heading: 'Remediation status', content: rep.remediation_status ?? '' },
        { heading: 'Reporting deadline', content: `${rep.deadline_hours ?? 72} hours from detection` },
      ];
  return {
    id: rep.id,
    incident_id: rep.incident_id,
    report_type: REPORT_TYPE[rep.framework] ?? 'gdpr_draft',
    title: rep.framework_label || rep.framework || 'Breach report draft',
    created_at: rep.generated_at || new Date().toISOString(),
    updated_at: rep.generated_at || new Date().toISOString(),
    status: 'draft',
    sections,
    disclaimer: REPORT_DISCLAIMER,
    exported_count: 0,
  };
}

const SCENARIO_CATEGORY: Record<string, ScenarioDefinition['category']> = {
  security: 'Security',
  deployment: 'Deployment',
  reliability: 'Availability',
};

/** Backend /api/v1/scenarios entry -> launcher card (describes what the agents actually do). */
export function toScenarioDefinition(sc: Json): ScenarioDefinition {
  return {
    id: sc.id as ScenarioId,
    name: sc.title,
    category: SCENARIO_CATEGORY[sc.category] ?? 'Security',
    is_mandatory_demo: Boolean(sc.featured) || ['S1', 'S2', 'S4', 'S6'].includes(sc.code),
    demonstrates: [sc.subtitle, ...(sc.expected_actions ?? [])].filter(Boolean).join(' · '),
    agents_involved: sc.agents_involved ?? [],
    expected_outcome: sc.verification_proof ?? '',
    simulated_payload_info: sc.trigger_description ?? '',
    estimated_duration_seconds: sc.estimated_duration_seconds ?? 5,
  };
}
